-- Thread 1 (sort 362): the-resurrection-of-the-righteous-vindicated-and-shining-in-wisdom-of-solomon-3-and-5
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-resurrection-of-the-righteous-vindicated-and-shining-in-wisdom-of-solomon-3-and-5',
       'The Resurrection of the righteous vindicated and shining — Wisdom of Solomon 3 and 5''s wisdom-stream witness to the firstfruits-substance the King walks at Matt 28:6-9',
       'Matt 28:6-9''s heavenly-messenger''s announcement (*He is not here: for he is risen, as he said*) + the King-of-Yashar''el (Israel)''s first-Resurrection-appearance to the faithful women (*All hail* + *go tell my brethren*) — read against the wisdom-stream''s direct articulation of the substantial-resurrection-of-the-righteous + the day-of-their-visitation-they-shall-shine + the reward-with-Yahuah substance in Wisdom of Solomon 3 + 5. Four moves: Wisdom of Solomon 3:7 names the time-of-visitation-they-shall-shine substance the King-of-Yashar''el (Israel)-as-firstfruits enacts at the empty-tomb (*Messiah (Christ) the firstfruits; afterward they that are Messiah''s (Christ''s) at his coming* per 1 Corinthians 15:20-23); Wisdom of Solomon 3:8 names the substantial-resurrected-righteous-shall-judge-the-nations-and-have-dominion substance the millennial-reign-on-the-earth-substance walks-out per Revelation 20:4-6 + Daniel 7:18, 22, 27; Wisdom of Solomon 5:15 names the righteous-live-for-evermore + reward-with-Yahuah substance the physical-Resurrection at v.9 enacts the operative-firstfruits-form of (the *they came and held him by the feet, and worshipped him* substance is NOT the Gnostic-spiritualized-resurrection the inherited-pattern walks-substantively-into); Wisdom of Solomon 5:16 names the glorious-kingdom + beautiful-crown + Father''s-right-hand-covering substance the inheritance-of-the-resurrected-righteous-substance the wisdom-stream had named the architecture for. The framework reads the cluster in continuity with the asleep-awaiting-the-first-resurrection substance per Red Line #11 + 1 Thessalonians 4:14-17 — NOT the inherited-Christian immediate-disembodied-soul-going-to-heaven substance. The King-of-Yashar''el (Israel)-as-the-firstfruits-substance is the operative-event of the resurrection-of-the-righteous architecture the wisdom-stream had named the prefiguring-substance for; the substantial-resurrection-day-of-the-citizens-of-the-kingdom is the substantial-substance at-the-King''s-coming. The framework reads this in close continuity with the S86 Matt 22 thread `the-resurrection-of-the-righteous-witnessed-by-the-mother-and-seven-sons-and-the-wisdom-stream` (anchored at the Sadducean-trap-question) — Matt 28 is the operative-event the wisdom-stream-architecture had named centuries before.',
