-- Thread 2 (sort 363): the-king-resurrected-and-ascended-sending-out-the-twelve-witnessed-in-ascension-of-isaiah-11 (FRAMEWORK-MAJOR)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-king-resurrected-and-ascended-sending-out-the-twelve-witnessed-in-ascension-of-isaiah-11',
       'The King resurrected and ascended sending out the Twelve — Ascension of Isaiah 11''s external-witness to the Matt 28 resurrection-and-Great-Commission architecture (FRAMEWORK-MAJOR)',
       'Matt 28''s three movements — the substantial-Resurrection at vv.1-10 + the substantial-chief-priests'' counter-narrative at vv.11-15 + the substantial-Great-Commission at vv.16-20 — read against the deepest external-witness articulation of the same architecture in the entire restored library: Ascension of Isaiah 11. Four moves: AI 11:19 names the adversary-roused-the-children-of-Yashar''el (Israel)-against-Him-not-knowing-who-He-was substance — the system-not-people architecture per Red Line #9 named explicitly at the wisdom-stream-vision-register (the system is the leadership-substance walked-substantively-into-the-bribery-cover-up at Matt 28:11-15; the people are the victims-of-the-substantial-deception-the-leadership-handed-them-in-good-faith; the *commonly reported among the Yahudim (Jews) until this day* substance is NOT categorical-anti-Yahudi (Jewish) substance per the framework''s rejection-of-the-inherited-Christian-collapse); AI 11:21 names THE direct verbal-anchor for the substantial-third-day-rise-again substance (*And likewise after the third day rise again and remain days*) — the substantial-Resurrection-substance the heavenly-messenger announces at the empty-tomb at v.6; AI 11:22 names THE direct verbal-anchor for the substantial-Great-Commission + Ascension substance (*And I saw when He sent out the Twelve Apostles and ascended*) — the substantial-sending-out-of-the-Twelve at v.19 + the implicit-Ascension named-explicitly at Acts 1:9-11; AI 11:32 names THE direct verbal-anchor for the substantial-Ascension-to-the-right-hand-of-the-Great-Glory substance (*And then I saw Him sit down on the right hand of that Great Glory*) — the operative-substance of Psalm 110:1 + Daniel 7:13-14 + the substantial *all power is given unto me in heaven and in earth* substance at v.18. Per Yoshi''s S32 sourcing-decision (api/seed.py:EDITION_PROFILES["ascension-isaiah"]), Ascension of Isaiah is the *first witness* aligning with the framework''s Formless-Father / Formed-of-the-Formless nature-of-God teaching at the deepest external-witness level — pre-Nicene, late-1st / early-2nd CE, before the Constantine-era doctrinal-construct hardened. The wisdom-stream-prophetic-substance the prophet-Yeshayahu (Isaiah) walks at the heavenly-vision-register and the gospel-substance the apostle-Mattithyahu (Matthew) walks at the historical-pivot cohere comprehensively at the Matt 28 architecture. FRAMEWORK-MAJOR.',
       sv.verse_id, ev.verse_id, 'complete_study', 363
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 28 AND sv.verse_number = 6
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 28 AND ev.verse_number = 20
