-- Thread 3 (sort 364): all-power-given-the-son-of-adam-enthroned-on-the-throne-of-glory-in-1-enoch-parables (FRAMEWORK-MAJOR)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'all-power-given-the-son-of-adam-enthroned-on-the-throne-of-glory-in-1-enoch-parables',
       'All power given the Son of Adam enthroned on the throne of glory — 1 Enoch 51, 61, and 62''s wisdom-stream witness to the substantial *all power is given unto me in heaven and in earth* at Matt 28:18 (FRAMEWORK-MAJOR)',
       'Matt 28:18''s *And Yahusha (Jesus) came and spake unto them, saying, All power is given unto me in heaven and in earth* — the substantial-Greek *pasa exousia* (all authority/power) — read against the wisdom-stream''s direct articulation of the substantial-Son-of-Adam-given-dominion-on-the-throne-of-glory architecture in 1 Enoch''s Parables (chs 37-71). Five moves: 1 Enoch 51:1 names the substantial-Elect-One-shall-arise + the earth-and-Sheol-shall-give-back-the-dead substance — the substantial-Resurrection-architecture the King walks at the firstfruits-event at Matt 28:6 + the citizens-at-the-first-resurrection per Revelation 20:4-6; 1 Enoch 51:2 names the substantial-Elect-One-shall-choose-the-righteous-and-holy substance — the post-harvest-sifting per Red Line #11 the substantial-all-power-given-substance enables; 1 Enoch 61:8 names the substantial-Head-of-Days-placed-the-Elect-One-on-the-throne-of-His-glory substance — the Father-Son relational-architecture per the Formless-Source / Formed-Expression grid (the Head-of-Days at 1 Enoch 61:8 is the Father; the Elect-One is the Son); 1 Enoch 62:6 names THE direct verbal-anchor for the substantial-Father-of-Spirits-seated-the-Elect-One-on-the-throne-of-His-glory substance — the wisdom-stream''s direct articulation of the substantial Daniel 7:13-14 dominion-and-glory-and-a-kingdom substance the King walks-out at v.18; 1 Enoch 62:9 names the substantial-Son-of-Adam-raising-up-and-putting-down-the-kings-and-the-mighty-from-their-thrones substance — the categorical-dominion-substance heaven-and-earth-substantively-comprehensively (NOT the inherited-Christian-spiritualized-kingdom-only-in-heaven substance). Per Red Line #12, the Son-of-Adam-architecture the framework reads runs through 1 Enoch 46-71''s named-figure-of-the-Son-of-Adam-Elect-One (the named-Standard the framework reads at the title-naming register; NOT the kaph-comparative case of Daniel 7:13 / Revelation 1:13 / Revelation 14:14 the Red Line carves-out separately). The substantial-substance: the King-of-Yashar''el (Israel) at the substantial-Resurrection-and-Ascension receives the substantial-Daniel-7:14-dominion-and-glory-and-a-kingdom substance the wisdom-stream had named at the throne-of-glory-substance for centuries before. The substantial-substance walks the substantial Psalm 110:1''s right-hand-of-the-Father + Psalm 8:6''s Adamic-dominion-restored (Hebrews 2:5-9''s last-Adam-substance) + Ephesians 1:20-22 + Philippians 2:9-11 at the apostolic-substance. FRAMEWORK-MAJOR.',
       sv.verse_id, ev.verse_id, 'complete_study', 364
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 28 AND sv.verse_number = 18
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 28 AND ev.verse_number = 18
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 365): panta-ta-ethne-as-the-scope-of-proclamation-because-the-sheep-are-scattered-in-jubilees-and-2-esdras-13 (FRAMEWORK-MAJOR — signature)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'panta-ta-ethne-as-the-scope-of-proclamation-because-the-sheep-are-scattered-in-jubilees-and-2-esdras-13',
       'Panta ta ethnē as the SCOPE-of-proclamation because the sheep are scattered through every nation — Jubilees 1''s gathering-from-the-nations + 2 Esdras 13''s ten-tribes-in-a-far-country (FRAMEWORK-MAJOR — the signature framework-load for Matt 28)',
       'Matt 28:19-20''s *Go ye therefore, and teach all nations* (Greek *poreuthentes oun mathēteusate panta ta ethnē*) + *teaching them to observe all things whatsoever I have commanded you* — the SIGNATURE FRAMEWORK-LOAD of Matt 28 — read against the wisdom-stream''s direct articulation of the substantial-scope-of-the-proclamation-because-the-sheep-are-scattered architecture per Red Line #11. The framework EXPLICITLY RULES OUT the inherited-Christian-inclusion-of-the-Gentiles-into-the-church reading: the substantial *panta ta ethnē* is NOT the substantial-categorical-Three-Categories-#3-nations-inclusion substance; the substantial-substance is the substantial-territorial-extension-of-the-Lost-Sheep-Mission-Scope LOCKED at Matt 10:5-6 (*go rather to the lost sheep of the house of Yashar''el (Israel)*) + Matt 15:24 (*I am not sent but unto the lost sheep of the house of Yashar''el (Israel)*) — the substantial-Great-Commission EXTENDS the mission TERRITORIALLY because the substantial-scattered-seed-of-both-houses is-substantively-among-the-territories-of-the-nations. The audience is the citizens-of-the-kingdom-scattered-among-the-territories-of-the-nations whom we do-not-know-by-sight; the proclamation goes broadly; those-who-hear-are-revealed-to-be-sheep-because-they-were-sheep-before-the-foundation-of-the-world (John 10:26-27 + Revelation 13:8 + 17:8). Five moves: 2 Esdras 13:40 names THE direct verbal-anchor for the ten-tribes-carried-away-into-another-land substance — the substantial-scattered-northern-house-of-Yashar''el (Israel)-substance the prophet-Hosheia (Hosea) had named the Lo-Ammi-substance for at Hosea 1:9-10; 2 Esdras 13:47 names the Father-staying-the-springs-of-the-stream-again substance for the substantial-second-recovery-gathering-of-the-ten-tribes-back-from-the-far-country — the substantial-substance Isaiah 11:11-12 walks (*Yahuah (the LORD) shall set his hand again the second time to recover the remnant of his people ... from the four corners of the earth*); Jubilees 1:15 names the Father-gathering-the-citizens-from-amongst-all-the-nations substance with-all-their-heart and-all-their-soul-and-all-their-strength (the Shema-substance of Deuteronomy 6:5 woven-into the gathering-architecture); Jubilees 1:23 names THE direct verbal-anchor for the substantial-circumcised-heart + holy-spirit-given substance the new-covenant of Jeremiah 31:31-34 + Ezekiel 36:26-27 walks — the operative-substance of the substantial *baptizing them in the name of the Father, and of the Son, and of the Ruach HaKodesh (Holy Spirit)* at v.19b and the *teaching them to observe all things* heart-Torah-substance at v.20 directly-closing the Matt 5:17-19 anti-antinomian-declaration bookend; Jubilees 1:25 names THE direct verbal-anchor for the substantial-Hosea 1:10 substance the apostle-Sha''ul (Paul) cites at Romans 9:25-26 (*ye are the sons of the living Elohim (God)*) — the substantial-Lo-Ammi-reversal-substance the substantial-scattered-seed-of-the-house-of-Yashar''el (Israel)-substance walks-out at the substantial-Father''s-second-recovery-substance. The substantial-three-category-architecture holds: house-of-Yahudah (Judah) + scattered-seed-of-the-house-of-Yashar''el (Israel) + nations. The substantial-Great-Commission walks the substantial-territorial-pursuit-of-the-scattered-seed-of-both-houses substantively-among-the-territories-of-the-nations — the audience is the citizens; the practice is broad proclamation; the nations'' place in the covenant-architecture is the substantial-receiving-of-the-priestly-instruction-substance from the gathered-remnant-of-the-twelve-tribes at the substantial-millennial-substance per Micah 4:1-3 + Isaiah 61:6 + Exodus 19:6 + Revelation 1:6 + 5:10 + 20:6. The framework''s rejection of-the-categorical-grafting-by-faith-confession substance is non-negotiable per Red Line #11. FRAMEWORK-MAJOR — the signature framework-load for Matt 28.',
       sv.verse_id, ev.verse_id, 'complete_study', 365
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 28 AND sv.verse_number = 19
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 28 AND ev.verse_number = 20
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 366): the-king-ascending-and-the-tribes-rising-each-over-his-tribe-in-testaments-of-the-twelve
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-king-ascending-and-the-tribes-rising-each-over-his-tribe-in-testaments-of-the-twelve',
       'The King ascending and the tribes rising each over his tribe — Testaments of the Twelve Patriarchs (Benjamin Ch 7-8 in the Charles concatenation) on the resurrection-architecture-paired-with-the-twelve-tribes-restoration the Great Commission walks-out from',
       'Matt 28:10''s *go tell my brethren that they go into Galilee* + Matt 28:16-20''s eleven-on-the-Galilee-mountain + Great-Commission — read against the wisdom-stream''s direct articulation of the substantial-King-ascending-from-Hades-to-heaven + the substantial-twelve-tribes-rising-each-one-over-his-tribe architecture in Testaments of the Twelve Patriarchs (Charles concatenation, Benjamin Ch 7-8 / TestXII chs 94-95, corresponding to traditional Test. Benjamin 9-10). Four moves: TestXII 94:5 names THE direct verbal-anchor for the substantial-King-ascending-from-Hades-and-passing-from-earth-into-heaven substance + the substantial-lowly-upon-earth-and-glorious-in-heaven kenosis-and-glorification architecture (the substance Philippians 2:6-11 walks at the apostolic-register) — the operative-substance of Matt 28:18''s *all power is given unto me in heaven and in earth* (the glorious-in-heaven half of the architecture the King reaches at the substantial-Resurrection-and-Ascension); TestXII 95:6 names the salvation-revealed-to-all-Gentiles substance — the substantial-revelation-of-the-Father''s-salvation going broadly-into-the-territories-of-the-nations-where-the-substantial-scattered-seed-of-both-houses-is-substantively-among per Red Line #11 (the substantial-substance is NOT categorical-grafting; the substance is broad-proclamation-because-the-sheep-are-scattered-among-the-nations + the substantial-Father-knows-his-sheep-by-substance per John 10:27 NOT-by-our-sighting); TestXII 95:7 names THE direct verbal-anchor for the substantial *Then shall we also rise, each one over our tribe, worshipping the King of heaven* substance — the substantial-twelve-tribes-rising-each-one-over-his-tribe architecture the substantial-twelve-thrones-substance walks per Matt 19:28 + Revelation 7:4-8 + Revelation 21:14 + the substantial *my brethren* substance the King walks at Matt 28:10 (Psalm 22:22 + Hebrews 2:11-12 + Matt 12:46-50 + Matt 25:40); TestXII 95:8 names the substantial-all-men-shall-rise-some-unto-glory-and-some-unto-shame substance (Daniel 12:2 carried-forward) + the substantial-judgment-of-the-substantial-house-of-Yashar''el (Israel)-first substance (1 Peter 4:17''s *judgment must begin at the house of Elohim (God)*) — the operative-substance of Matt 28:18''s substantial-all-power-given-substance. The framework reads the cluster in continuity with the S87 Matt 25 thread `my-brethren-substance-distinguishing-the-seed-of-promise-from-the-categorical-nations` (FRAMEWORK-MAJOR) — the substantial *my brethren* at Matt 28:10 walks the substantial-twelve-tribes-restoration-architecture-substance per Red Line #11. The substantial-substance the wisdom-stream walks at TestXII 95:7 names the substantial-resurrection-of-the-tribes the King''s-firstfruits-Resurrection-substance walks-toward at the substantial-first-resurrection of-the-citizens-at-the-King''s-coming per Revelation 20:4-6.',
       sv.verse_id, ev.verse_id, 'complete_study', 366
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 28 AND sv.verse_number = 10
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 28 AND ev.verse_number = 20
