-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s156_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 28
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-resurrection-of-the-righteous-vindicated-and-shining-in-wisdom-of-solomon-3-and-5',
     'the-king-resurrected-and-ascended-sending-out-the-twelve-witnessed-in-ascension-of-isaiah-11',
     'all-power-given-the-son-of-adam-enthroned-on-the-throne-of-glory-in-1-enoch-parables',
     'panta-ta-ethne-as-the-scope-of-proclamation-because-the-sheep-are-scattered-in-jubilees-and-2-esdras-13',
     'the-king-ascending-and-the-tribes-rising-each-over-his-tribe-in-testaments-of-the-twelve'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-resurrection-of-the-righteous-vindicated-and-shining-in-wisdom-of-solomon-3-and-5',
     'the-king-resurrected-and-ascended-sending-out-the-twelve-witnessed-in-ascension-of-isaiah-11',
     'all-power-given-the-son-of-adam-enthroned-on-the-throne-of-glory-in-1-enoch-parables',
     'panta-ta-ethne-as-the-scope-of-proclamation-because-the-sheep-are-scattered-in-jubilees-and-2-esdras-13',
     'the-king-ascending-and-the-tribes-rising-each-over-his-tribe-in-testaments-of-the-twelve'
   );

  RAISE NOTICE 'S156 Matt 28 verify: extras xrefs from canon/matthew/28 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 Matt-28 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
